from datetime import datetime
import numpy as np

class MovieBookingSystem:
    TIME_FORMAT = '%H:%M'
    AVAILABLE = 0
    BOOKED = 1

    def __init__(self):
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        movie = {
            'name': name,
            'price': price,
            'start_time': datetime.strptime(start_time, self.TIME_FORMAT),
            'end_time': datetime.strptime(end_time, self.TIME_FORMAT),
            'seats': np.zeros((n, n))
        }
        self.movies.append(movie)

    def find_movie_by_name(self, name):
        for movie in self.movies:
            if movie['name'] == name:
                return movie
        return None

    def is_seat_available(self, movie, seat):
        return movie['seats'][seat[0]][seat[1]] == self.AVAILABLE

    def mark_seat_as_booked(self, movie, seat):
        movie['seats'][seat[0]][seat[1]] = self.BOOKED

    def book_ticket(self, name, seats_to_book):
        movie = self.find_movie_by_name(name)
        if movie is None:
            return "Movie not found."

        for seat in seats_to_book:
            if not self.is_seat_available(movie, seat):
                return "Booking failed."
            self.mark_seat_as_booked(movie, seat)
        return "Booking success."

    def is_within_time_range(self, movie, start_time, end_time):
        return start_time <= movie['start_time'] and movie['end_time'] <= end_time

    def available_movies(self, start_time_str, end_time_str):
        start_time = datetime.strptime(start_time_str, self.TIME_FORMAT)
        end_time = datetime.strptime(end_time_str, self.TIME_FORMAT)

        available = [
            movie['name'] for movie in self.movies
            if self.is_within_time_range(movie, start_time, end_time)
        ]
        return available
